def demo():
    """Demonstrate the OpenEvolve PES integration."""
    
    print("\n" + "="*70)
    print("  OpenEvolve PES Integration Demo")
    print("  Enhancing OpenEvolve Outputs with Content-Agnostic Evolution")
    print("="*70)
    
    # Sample code that might come from OpenEvolve
    code = '''def calculate_payment(amount, discount_code=None, payment_method="credit_card"):
    """Calculate payment with tax, discounts, and fees."""
    subtotal = amount
    discount = 0
    
    # Apply discount
    if discount_code == "SAVE10":
        discount = subtotal * 0.10
    elif discount_code == "SAVE20":
        discount = subtotal * 0.20
    
    # Calculate tax
    taxable = subtotal - discount
    tax = taxable * 0.085
    
    # Payment fee
    fee = 0
    if payment_method == "credit_card":
        fee = subtotal * 0.029
    elif payment_method == "debit_card":
        fee = subtotal * 0.015
    
    total = taxable + tax + fee
    return {"subtotal": subtotal, "discount": discount, "tax": tax, "fee": fee, "total": total}'''
    
    problem_description = "Calculate payment with tax, discounts, and payment method fees"
    
    # Tests that OpenEvolve might generate
    tests = [
        {"name": "Basic payment", "input": {"amount": 100}, "expected": {"total": 111.4}, "function": "calculate_payment"},
        {"name": "10% discount", "input": {"amount": 100, "discount_code": "SAVE10"}, "expected": {"discount": 10}, "function": "calculate_payment"},
        {"name": "PayPal fee", "input": {"amount": 150, "payment_method": "paypal"}, "expected": {"fee": 5.25}, "function": "calculate_payment"},
    ]
    
    print("\nOriginal Code (from OpenEvolve):")
    print(code)
    
    print("\n" + "-"*70)
    print("Enhancing with PES system...")
    
    result = enhance_openevolve_code(
        code=code,
        tests=tests,
        problem_description=problem_description,
        max_iterations=5
    )
    
    print(f"\nEnhancement Result:")
    print(f"  Success: {result.success}")
    print(f"  Tests Generated: {result.tests_generated}")
    print(f"  Tests Passed (After): {result.tests_passed_after}/{result.tests_generated}")
    print(f"  Improvements: {result.improvements}")
    
    if result.error:
        print(f"  Error: {result.error}")
    
    if result.enhanced_code:
        print(f"\nEnhanced Code:")
        print(result.enhanced_code)
    
    return result


if __name__ == "__main__":
    demo()
